import{_ as a}from"./chunks/1b092ffa9f7d3d601cd8.CHFravEy.js";import{_ as p,C as o,o as l,c as n,j as t,a as s,E as h,a5 as i}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"未来将只有一条职业道路","description":"","frontmatter":{"title":"未来将只有一条职业道路","originalTitle":"There Will Only Be 1 Career Path In The Future","date":"2022-05-07","originalUrl":"https://thedankoe.com/letters/the-future-of-work-will-be-play/","minutes":10,"sourceHash":"98b7428b9ff30bafc51c26b03d0f443e797c9af22897a7140bab613cf943285c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-of-work-will-be-play/"}]]},"headers":[],"relativePath":"letters/the-future-of-work-will-be-play.md","filePath":"letters/the-future-of-work-will-be-play.md"}'),c={name:"letters/the-future-of-work-will-be-play.md"};function f(u,e,d,m,b,k){const r=o("ArticleMeta");return l(),n("div",null,[e[0]||(e[0]=t("h1",{id:"未来将只有一条职业道路",tabindex:"-1"},[s("未来将只有一条职业道路 "),t("a",{class:"header-anchor",href:"#未来将只有一条职业道路","aria-label":'Permalink to "未来将只有一条职业道路"'},"​")],-1)),h(r),e[1]||(e[1]=i('<p><a href="https://www.youtube.com/embed/oNV08CLn6zI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/106NaVTyOma1Fav4HqiUEL?si=9738c0a07ad343ba&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>过去这一个月，我意识到了我生活（以及许多其他人生活）中的一个共同主题。</p><p><em>痴迷</em>。</p><p>小时候，我痴迷于寻找一种更好的生活方式。我不知道是什么激发了这一点。<strong>我只知道我是一个沉默的观察者。</strong> 无论去哪里，我都会密切关注人们的行为。不是带有评判性地看，而是以一种敏锐洞察的方式。</p><p>那个人是如何走到人生那一步的？他们为什么看起来是那个样子？是因为他们每天早上都要去麦当劳得来速（drive-thru）买早餐吗？两个香肠加蛋麦满分配一大杯冰咖啡（别忘了还要额外加3泵糖浆！）？许多事情让我感到不解。</p><p>其中之一就是传统的职业道路。上学。在18岁时<em>自以为</em>知道自己想做什么（而实际上这只是文化条件反射让你这么做的）。初入社会<em>或许</em>能找到一份好工作。<em>或许</em>能享受生活，尽管你对自己一天中70%的时间毫无掌控权。<em>或许</em>能拥有自由，随心所欲地支配时间……那是在65岁的时候。赶紧给我报名吧！（才怪）</p><p>不。我不喜欢那样。一个“安稳”的未来听起来并没那么安稳。所以我把时间花在健身房里，在社交媒体上向我想成为的那种人学习，学习任何能帮助我的技能，并且在7个以上的商业模式上栽了跟头。</p><p>补充一句：我发现这是我品牌中缺失的一块。所以我将在6月7日推出《数字经济学》（Digital Economics）。这将是一个现代商业学位（由真正懂现代在线商业的人授课）。技能获取、品牌建设、快速内容创作，以及（在30天内）创造一个无人能与你竞争的专属细分领域。<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">这是获取早鸟更新的候补名单。</a></p><p>当一切融会贯通时，我开始看到成功的曙光。在过去的4年里，我拼凑出了完整的拼图。以下是我希望自己18岁时就能知道的事情：</p><h2 id="未来的职业道路" tabindex="-1">未来的职业道路 <a class="header-anchor" href="#未来的职业道路" aria-label="Permalink to &quot;未来的职业道路&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>未来的职业道路</p><p>未来的工作将不再是工作。<em>它将是游戏。</em></p><p>人类的心理天生就是为了生存而设定的。创业就是现代的生存方式。</p><blockquote><p>过去的人们在自己小小的社区内狩猎、采集、交易和赚钱。\\</p><p>互联网让我们有机会在我们自己无限的社区内狩猎、采集、交易和赚钱。\\</p><p>回归自然。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1522191336241254400?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 5, 2022</a></p></blockquote><p>我们无法控制人类的进化。道路已经铺好，并且正在我们眼前迅速展开。那些搭上这趟列车的人将会生存下来，而其他人则会经历神经生物学上的衰退。</p><p>好多巴胺 VS 坏多巴胺。追求你的好奇心，有所发现，并能够在一个从企业向个人转变的世界中维持这种生活方式。挖掘你的创造天才，创造解决问题的方法，浓缩信息，并提升集体的福祉。</p><h3 id="追求你的好奇心" tabindex="-1">追求你的好奇心 <a class="header-anchor" href="#追求你的好奇心" aria-label="Permalink to &quot;追求你的好奇心&quot;">​</a></h3><blockquote><p>特有知识是通过追求你真正的好奇心和热情找到的，而不是追逐眼下的热门。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1002105081855016961?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 31, 2018</a></p></blockquote><p>我们在这些信中多次谈到了好奇心，<a href="https://thedankoe.com/if-you-feel-lost-understand-these-3-phases-of-life/" target="_blank" rel="noreferrer">特别是在上一封信里</a>。</p><p>在我们生命最初的18年里，文化的设定就是为了剥夺我们孩童般的好奇心。这既是祝福也是诅咒。对那些意识到这一点的人来说是祝福，对那些没有意识到的人来说则是诅咒。</p><p>好奇心是通向做你想做之事的路径——而不是做别人想让你做的事。学校系统给我们分配了我们可能感兴趣也可能不感兴趣的学习材料。它可能会激发你在业余时间探索某些事物的好奇心，但孩子们很少这么做。尤其是当他们的父母冲他们大吼着让去做作业的时候。</p><p>你通过质疑而不是妥协应对来追求你的好奇心。</p><p>“如果我学会了那项技能会怎样？”</p><p>“如果我改善了我的健康状况会怎样？”</p><p>“如果我创办了那家公司会怎样？”</p><p>“如果我失败了呢？如果我没有失败呢？如果我坚持到底呢？世界会毁灭吗？当然不会。”</p><p>在一系列问题之后，接踵而至的就是对未知的探索。行动。寻找资源进行在线自我教育。让新的发现引导你走上另一条未知的道路。重复这个过程，直到你把所有的点都连接起来。</p><p>幸运的是，我们生活在一个任何东西都可以变现的世界里。如果你知道如何快速学习、打造一项报价（offer）并进行销售——你只需在网上谈论、学习和教授你好奇的事物，就能建立分发渠道。</p><h3 id="媒介与信息" tabindex="-1">媒介与信息 <a class="header-anchor" href="#媒介与信息" aria-label="Permalink to &quot;媒介与信息&quot;">​</a></h3><p>我有一个理论。这个理论就是，作为人类，我们正在网上绘制集体意识的图谱。</p><p>创作者、个人品牌、“思想领袖”和在线教育者正以指数级的速度加快进化的步伐。我们通过课程、系统、分步指南和指导来浓缩信息，以易于消化的方式提炼多年的经验。过去需要处理6000万比特信息的事情，现在只需1000万比特。</p><p>我们可以学得更多、行动更快、做出新发现，并以同样的方式传承我们自己的经验教训。有些人认为这就是生命的意义，而当其他人在为自己的未来建立巨大的杠杆时，有些人却在袖手旁观。与此同时，那些人正在追求自己独特的好奇心，这将使每个人都能在商业中走向一个独特的、未饱和的方向。</p><p>这正是人类所做的。他们为了生存而模仿。我们模仿父母、老师和朋友，以学习如何在这个世界上立足运作。许多人就止步于此了。聪明的模仿发生在这一切之后。你向那些正在浓缩你所好奇的信息的人学习，剖析它，理解它，并体验它。怎么做？通过在网上记录你所学、所建和所体验的东西。要正确做到这一点，你需要了解是什么能吸引注意力。也就是说，如何以一种能吸引其他追求好奇心的人的方式来提炼你的所学。</p><p>如果你想获得我用于更快学习的“聪明的模仿”流程，<a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">下载我免费的7天挑战。</a> 它将使你的创意输出增加10倍，并让内容创作的想法源源不断。（我就是这样写出这些新闻简报的）。</p><p>好了，言归正传。要追求你内在的好奇心，你可以走两条路。</p><p><strong>1) 媒体（信息）</strong></p><p>媒体是我们无需当面也能与其他人类交流的方式。互联网的前端就是媒体。这就是你吸引注意力来教育、娱乐和启发他人的方式。这就是你吸引受众、公开学习以及分发你那可以出售的、像压缩包一样浓缩的知识的方式（同时还能加速进化并提升集体福祉）。</p><p>要掌握媒体，就要学习营销、说服、销售、心理学、认识论、哲学，以及其他所有能让你理解心智的学问。最好的方法是公开学习。也就是说，通过建立一个真实世界的项目来学习。基于你的好奇心开一个社交媒体账号。制作视频、播客、文章、帖子等。把它当作一个爱好，一场让你学习是什么在驱动其他人类行为的游戏。</p><p>往少了说，你已经创建了一个公开的作品集，并培养了无需学位就能让你获得高薪工作的现代技能。媒体工作非常抢手。你可以为营销和媒体机构、创意人士、其他个人品牌工作，还有许多其他选择。然后，你可以用增加的收入来为你的创业之旅提供燃料（而且你已经掌握了媒体游戏的玩法）。</p><p>往多了说，你为你的未来建立了杠杆，创建了一个基于系统的项目，并赚到了远超你过上幸福生活所需的钱。</p><p>无论哪种方式，你都赢了。开始创作吧。</p><p>Modern Mastery HQ ——这个私密社区——有超过1000名成员正在做这件事。<a href="https://modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">Koe Letter 的读者只需5美元即可加入。</a></p><p><strong>2) 代码（媒介）</strong></p><p>科技界在过去十年里迎来了爆发。科技，具体来说是代码，是媒体的载体。它允许我们以结构化的方式打包信息。它允许我们在数字经济中容纳信息、产品、服务以及其他一切事物。它是互联网的后端。</p><p>同样，你可以学习编程，在大约6个月内找到一份不需要学位的工作，赚一大笔钱，然后转型去做你想做的任何事。当我在退学前的大学最后一年里，代码就是我的好奇心所在。我上了一门基础的 HTML 和 CSS 课，就迷上了，并开始通过 YouTube 视频和课程进行自我教育。在媒体方面失败后，我最终在一家网页设计机构找到了一份工作。我用这笔收入来为我的业务提供资金，并最终在自由职业中取得了成功。我把学到的东西拿出来，在网上谈论它，打包成一个系统，然后以我的个人品牌出售。</p><p>编程方面还有更多东西，比如区块链和 Web3，但我目前还不能让我正在构建的东西分散了我的注意力。所以我就把这部分留给你的好奇心吧 🙂</p><p><strong>3) 强悍组合</strong></p><p>所有这一切的美妙之处在于：</p><p>世界上程序员的技术变得如此之好，以至于无代码工具如雨后春笋般涌现。任何人都可以建立网站、电子邮件列表、博客、产品、会员制、社区以及其他能让他们在网上发挥媒体技能的东西。</p><p>有了这些无代码工具，普通人只需打造一个个人品牌，就能同时学习媒体和代码。你通过学习和发布内容来在沟通方面自我教育，你通过将这些信息安置在你的网站、登录页和电子邮件列表中来在代码方面自我教育。</p><h3 id="建立分发渠道-然后建立任何你想建立的东西" tabindex="-1">建立分发渠道，然后建立任何你想建立的东西 <a class="header-anchor" href="#建立分发渠道-然后建立任何你想建立的东西" aria-label="Permalink to &quot;建立分发渠道，然后建立任何你想建立的东西&quot;">​</a></h3><blockquote><p>建立分发渠道，然后建立任何你想建立的东西。</p><p>— jckbtchr (@jackbutcher) <a href="https://twitter.com/jackbutcher/status/1395945544430854144?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 22, 2021</a></p></blockquote><p>正如我们所学到的，任何人都可以建立分发渠道。分发渠道只是潜在流量一种花哨的说法。受众就是流量。电子邮件列表就是流量。社区就是流量。你的人脉网络就是流量。所有这些都可以被导向你的数字产品或服务。</p><p>在我们学习驾驭互联网的过程中，世界极度渴望人与人之间的连接。去中心化是一个热门话题。大企业不可信。正规教育不可信。一个个分布式的个体中心（个人品牌）如雨后春笋般涌现，来提供这种人际连接并进行教育。每个人都可以追求自己的好奇心，做自己热爱的事——只要他们意识到这个机会。</p><blockquote><p>“在这个星球上有近70亿人。我希望有一天，这里也会有近70亿家公司。” — Naval</p></blockquote><p>媒体是信息（内容）。代码是房地产（容纳内容的地方）。品牌是分发（你如何吸引人们来消费你的内容）。通过建立这些数字资产，你可以创建一个基于系统的数字产品或服务（浓缩信息，这是很有价值的），并从你的好奇心视角来谈论你的专业知识（这样就没有了“竞争”）。</p><h3 id="赚取财富" tabindex="-1">赚取财富 <a class="header-anchor" href="#赚取财富" aria-label="Permalink to &quot;赚取财富&quot;">​</a></h3><p>到目前为止，我们已经探讨了好奇心、媒体、代码和分发这几个步骤。但你要分发什么呢？数字产品或服务。那些通过加速教育或解决问题来直接影响人类体验的东西。</p><p>有三种方法可以做到这一点：</p><p><strong>1) 代办服务 (Done For You)</strong></p><p>代办服务是指自由职业或机构代运营（agency work）之类的事情。有人遇到了问题，你有一个独特的系统来解决它，他们雇佣你，你就替他们解决问题。</p><p><strong>2) 陪跑服务 (Done With You)</strong></p><p>陪跑服务是指咨询、教练或指导类的工作。你不是替别人做某事，而是引导他们了解你的系统。你在教导他们、教育他们如何改善生活的某个方面。你帮助他们跨越你曾经经历过的那些障碍。</p><p><strong>3) 自助服务 (Do It Yourself)</strong></p><p>自助服务适用于数字产品。你通过无代码工具将你的系统打包成易于消化的形式，并通过互联网进行无限分发。你可以直接进入数字产品游戏，但你需要分发渠道才能很好地变现。当你没有分发渠道时，做自由职业或咨询服务可以帮助你开发系统、获得结果，并在没有大量受众的情况下赚取收入。</p><p>这就是你赚取财富的方式。通过努力向上攀登，开发你的系统，将其打包，并以“零边际复制成本”进行分发。</p><blockquote><p>财富需要杠杆。商业杠杆来自于资本、劳动力，以及没有边际复制成本的产品（代码和媒体）。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1002106317064949763?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2018年5月31日</a></p></blockquote><h3 id="开始构建杠杆" tabindex="-1">开始构建杠杆 <a class="header-anchor" href="#开始构建杠杆" aria-label="Permalink to &quot;开始构建杠杆&quot;">​</a></h3><p>关于这个话题，我可以滔滔不绝地讲下去，我也会在未来的信件中继续讲，但现在——直接开始吧。这就是你学习的方式。使用我的 <a href="https://shop.thedankoe.com/planner" target="_blank" rel="noreferrer">Power Planner</a> 来制定你品牌的使命和愿景（你正在引导人们走向何方、你打算研究什么，以及你打算在公开场合学习什么）。然后，使用我的<a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">智能模仿流程</a>来辅助记录你思想的过程。</p><p>这就是我们所有人都在做的事情。在网上绘制一个巨大的思想版图（就像宇宙一样）。加入这场派对，收获神经生物学上的好处，或者等到你别无选择时再行动。我不喜欢“散布恐惧”，但似乎真的没有别的路可走了。你要么顺应自然而活，要么成为人为的产物。也就是说，要么去创造，要么被创造。</p><p>如果你想每周六早上在收件箱里收到 The Koe Letter，<a href="https://links.thedankoe.com/#letter" target="_blank" rel="noreferrer">可以在这里订阅。</a></p><hr><p><a href="/en/letters/the-future-of-work-will-be-play">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',75))])}const q=p(c,[["render",f]]);export{w as __pageData,q as default};
